import numpy as np

def _normalize(matrix: "np.ndarray", **kwargs) -> "np.ndarray":
    norms = np.linalg.norm(matrix, **kwargs)
    return matrix / np.clip(norms, 1e-12, None)

def main(
    raw_query_vector: "list[float]",
    rows: "Iterable[dict[str, Any]]",
    embedding_column: "str",
    limit: "int",
    min_score: "float | None" = None,
):
    if not rows:
        return []

    query_vector = _normalize(np.asarray(raw_query_vector, dtype=np.float32))
    vectors = [[float(x) for x in row[embedding_column]] for row in rows if row[embedding_column]]
    matrix = np.asarray(vectors, dtype=np.float32)
    if matrix.shape[1] != query_vector.shape[0]:
        raise ValueError(f"Stored vectors have {matrix.shape[1]} dimensions but the query has {query_vector.shape[0]}.")
    scores = _normalize(matrix) @ query_vector
    order = np.argsort(-scores)[: max(limit, 0)]

    results = []
    for i in order:
        score = float(scores[i])
        if min_score is not None and score < min_score:
            continue
        (case_id, timestamp) = rows[i]["memory_ref"].split("/", 1)
        results.append(
            {
                "summary": rows[i]["summary"], 
                "content": rows[i]["content"], 
                "case_id": case_id, 
                "timestamp": timestamp, 
                "score": score
            }
        )
    return results

